 "content": "from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active_rows = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    bands = []
    for r in active_rows:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) >= 2:
        # The corresponding leading rows of the two pattern bands encode
        # matching horizontal runs; mark the missing continuation in the shorter.
        a, b = bands[0][0], bands[1][0]
        ends = [max(c for c, v in enumerate(grid[r]) if v != bg) for r in (a, b)]
        short_idx = 0 if ends[0] < ends[1] else 1
        r = (a, b)[short_idx]
        lo, hi = ends[short_idx] + 1, max(ends)
        for c in range(lo, hi + 1):
            if out[r][c] == bg:
                out[r][c] = 1
    return out

