def transform(grid):
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Group non-background rows into objects separated by empty rows.
    active = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    bands = []
    for r in active:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    # The demos show a partial repeated object completed by the matching full
    # object: copy the rightward continuation of the lower band into its match.
    if len(bands) >= 2:
        upper, lower = bands[0], bands[1]
        for r in upper:
            # matching rows are the top-aligned row in both objects
            rr = lower[0] + (r - upper[0])
            if rr >= len(grid) or rr not in lower:
                continue
            # Fill the trailing background after the upper pattern to the edge
            # where its matching lower row has a continuation color.
            cols = [c for c,v in enumerate(grid[r]) if v != bg]
            if not cols:
                continue
            start = max(cols) + 1
            for c in range(start, len(grid[r])):
                if grid[rr][c] != bg:
                    out[r][c] = 1
    return out

