 "content": "from collections import Counter


def transform(grid):
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active_rows = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    bands = []
    for r in active_rows:
        if not bands or r != bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)

    # Find matching portions of two separate repeated pattern bands.  The
    # intended (shorter) copy differs from the other by exactly one foreground
    # cell; recolor that missing cell with 1.
    best = None
    for bi in range(len(bands)):
        for bj in range(bi + 1, len(bands)):
            arows, brows = bands[bi], bands[bj]
            if len(arows) != len(brows):
                continue
            h = len(arows)
            for width in range(1, len(grid[0]) + 1):
                for ac in range(len(grid[0]) - width + 1):
                    for bc in range(len(grid[0]) - width + 1):
                        diffs = []
                        foreground = 0
                        for dr in range(h):
                            for dc in range(width):
                                av = grid[arows[dr]][ac + dc]
                                bv = grid[brows[dr]][bc + dc]
                                foreground += (av != bg) + (bv != bg)
                                if (av != bg) != (bv != bg):
                                    diffs.append((dr, dc, av, bv))
                                    if len(diffs) > 1:
                                        break
                            if len(diffs) > 1:
                                break
                        if len(diffs) == 1 and foreground >= 4:
                            dr, dc, av, bv = diffs[0]
                            # Mark the absent foreground pixel in the later copy.
                            if bv == bg and av != bg:
                                score = h * width
                                candidate = (score, brows[dr], bc + dc)
                                if best is None or candidate[0] > best[0]:
                                    best = candidate
    if best is not None:
        _, r, c = best
        out[r][c] = 1
    return out
